async (page) => {
  const base = 'http://127.0.0.1:8815/docs/china-fork/prototype/';
  const passed = [];
  const errors = [];
  const external = [];
  page.on('pageerror', error => errors.push(error.message));
  page.on('request', request => { if (!request.url().startsWith('http://127.0.0.1:8815/') && !request.url().startsWith('data:')) external.push(request.url()); });
  const check = (condition, message) => { if (!condition) throw new Error(message); passed.push(message); };
  const text = selector => page.locator(selector).innerText();
  const click = name => page.getByRole('button', { name, exact: true }).click();
  await page.setViewportSize({ width: 1100, height: 980 });
  await page.goto(base + 'index.html');
  await click('重置示例数据');
  check(await text('#day-energy') === '870.5', '首页合计来自示例记录，显示精度不产生1kcal差额');
  await click('前一天');
  check(await text('#day-energy') === '0', '前一天显示独立空日记');
  await click('后一天');
  check(await text('#day-energy') === '870.5', '切回原日期保留日记');
  check(await page.getByRole('region', { name: /记录$/ }).count() === 4, '四餐均有独立记录区域');
  await page.locator('#phone').screenshot({ path: 'output/playwright/m1/home.png' });

  await click('向午餐添加食品');
  await page.getByRole('searchbox', { name: '搜索食品名称或品牌' }).fill('蛋');
  check(await page.getByRole('button', { name: '查看家常鸡蛋羹', exact: true }).count() === 1, '单字中文可搜索本地食品');
  await page.getByRole('searchbox').fill('牛奶');
  await click('查看纯牛奶');
  await page.getByRole('spinbutton', { name: '摄入量', exact: true }).fill('250');
  check(await text('#intake-energy') === '152.5', '250mL按每100mL基准实时得到152.5kcal');
  check(await page.locator('.quick-amounts .active').count() === 0, '手动输入非预设摄入量时不保留过期快捷选中状态');
  const options = await page.locator('#quantity-unit option').allTextContents();
  check(!options.includes('g'), '没有密度时不提供克与毫升混换');
  await page.getByRole('combobox', { name: '计量单位' }).selectOption('serving');
  check(await page.locator('#quantity').inputValue() === '1' && await text('#intake-energy') === '152.5', '切换250mL到1盒保持营养总量');
  await page.getByRole('combobox', { name: '记录餐次' }).selectOption('snack');
  await page.locator('#save-intake').click();
  check(await text('#day-energy') === '1,023', '食品可记录到用户选择的餐次并更新汇总');
  check(await page.getByRole('region', { name: '加餐记录', exact: true }).getByRole('button', { name: '修改纯牛奶的摄入量' }).count() === 1, '餐次选择实际影响日记归属');
  await click('修改纯牛奶的摄入量');
  await page.getByRole('combobox', { name: '计量单位' }).selectOption('ml');
  await page.getByRole('spinbutton', { name: '摄入量', exact: true }).fill('300');
  await page.locator('#save-intake').click();
  check(await text('#day-energy') === '1,053.5', '修改记录量只更新当前日记');
  await click('修改纯牛奶的摄入量');
  await click('再记一份');
  check(await text('#day-energy') === '1,236.5', '重复添加创建独立记录');
  await click('撤销');
  check(await text('#day-energy') === '1,053.5', '撤销重复添加恢复合计');
  await click('修改纯牛奶的摄入量');
  await click('删除记录');
  check(await text('#day-energy') === '870.5', '删除记录扣除当前摄入');
  await click('撤销');
  check(await text('#day-energy') === '1,053.5', '删除可撤销并恢复原记录');

  await click('向午餐添加食品');
  await page.getByRole('searchbox').fill('黑芝麻');
  await click('创建“黑芝麻”');
  check(await page.getByRole('textbox', { name: '食品名称', exact: true }).inputValue() === '黑芝麻', '无结果创建保留搜索词');
  await page.getByRole('spinbutton', { name: '热量', exact: true }).fill('200');
  await page.getByRole('spinbutton', { name: '蛋白质', exact: true }).fill('10');
  await page.getByRole('spinbutton', { name: '脂肪', exact: true }).fill('5');
  await page.getByRole('spinbutton', { name: '碳水化合物', exact: true }).fill('15');
  await click('高级模式');
  await page.getByRole('spinbutton', { name: '锌', exact: true }).fill('2.3');
  await page.getByRole('spinbutton', { name: '维生素 B6', exact: true }).fill('0');
  await click('简单模式');
  await click('高级模式');
  check(await page.getByRole('spinbutton', { name: '锌', exact: true }).inputValue() === '2.3', '切换简单高级不丢高级营养值');
  check(await page.getByRole('spinbutton', { name: '维生素 B6', exact: true }).inputValue() === '0', '已知零保持为零');
  await page.getByRole('combobox', { name: '热量单位', exact: true }).selectOption('kJ');
  check(await page.getByRole('spinbutton', { name: '热量', exact: true }).inputValue() === '836.8', '编辑kcal到kJ转换正确');
  await page.getByRole('combobox', { name: '热量单位', exact: true }).selectOption('kcal');
  check(await page.getByRole('spinbutton', { name: '热量', exact: true }).inputValue() === '200', '切回kcal保留标示值');
  await page.locator('summary').filter({ hasText: '来源与个人核对' }).click();
  await page.locator('#checked-food').check();
  await click('保存并继续记录');
  check((await text('#form-error')).includes('核对依据'), '没有依据不能标记个人核对');
  await page.getByRole('combobox', { name: '数据依据' }).selectOption('label');
  await page.getByRole('textbox', { name: '来源或核对说明' }).fill('示例包装标签，已核对每100g基准');
  await click('保存并继续记录');
  check(await page.getByRole('heading', { name: '黑芝麻', exact: true }).count() === 1, '填来源后可保存自建食品并继续记录');
  check(await page.locator('.detail-energy').first().innerText() === '200kcal', '宏量估算差异不覆盖标示热量');
  await page.locator('summary').filter({ hasText: '更多营养素' }).click();
  check((await page.locator('tr').filter({ hasText: /^锌/ }).innerText()).includes('2.3'), '保存后保留高级锌字段');
  check((await page.locator('tr').filter({ hasText: /^钠/ }).innerText()).includes('—'), '未填写的钠保持未知');
  await page.locator('#save-intake').click();
  await click('向午餐添加食品');
  await page.getByRole('searchbox').fill('黑芝麻');
  check(await page.getByRole('button', { name: '查看黑芝麻', exact: true }).count() === 1, '新建食品下次可从本地搜索找到');
  await page.locator('#phone').screenshot({ path: 'output/playwright/m1/search.png' });

  await page.getByRole('searchbox').fill('鸡胸肉');
  await click('查看鸡胸肉（熟）');
  await click('修正数据，另存为我的食品');
  await page.getByRole('spinbutton', { name: '热量', exact: true }).fill('180');
  await click('保存并继续记录');
  check(await page.locator('.detail-energy').first().innerText() === '180kcal', '公共食品修正可保存为自己的版本');
  await page.locator('summary').filter({ hasText: '来源与个人核对' }).click();
  check((await page.locator('details').first().innerText()).includes('原始来源') && (await page.locator('details').first().innerText()).includes('尚未标记'), '修正版保留原始来源且不自动核验');
  await page.getByRole('button', { name: '01 饮食日记 →', exact: true }).click();
  await click('修改鸡胸肉（熟）的摄入量');
  check((await page.locator('.basis-title').innerText()).includes('165 kcal') && await text('#intake-energy') === '198', '修正模板不改变已有日记营养快照');

  await page.getByRole('button', { name: '02 食品搜索 →', exact: true }).click();
  await page.locator('#network-mode').selectOption('offline');
  check((await page.locator('#search-results').innerText()).includes('当前离线'), '离线状态准确说明只提供本地结果');
  check(await page.getByRole('button', { name: '查看黑芝麻', exact: true }).count() === 1, '离线仍能查找自建食品');
  await page.locator('#network-mode').selectOption('error');
  check((await page.locator('#search-results').innerText()).includes('已保留本地结果'), '公共来源失败不伪装为没有食品');
  await page.locator('#network-mode').selectOption('online');
  await click('扫描条形码');
  await click('国内样例 · 数据缺失');
  check(await page.locator('#save-intake').isDisabled(), '条码产品无营养信息时不伪造热量');
  await page.getByRole('button', { name: '02 食品搜索 →', exact: true }).click();
  await click('扫描条形码');
  await click('国外样例 · Nutella');
  check(await page.getByRole('heading', { name: 'Nutella 榛子可可酱', exact: true }).count() === 1, '国外样例条码可进入详情');
  await click('收藏食品');
  await page.locator('summary').filter({ hasText: '来源与个人核对' }).click();
  check((await page.locator('details').first().innerText()).includes('尚未标记'), '收藏操作不自动产生个人核对状态');
  await page.getByRole('button', { name: '02 食品搜索 →', exact: true }).click();
  await click('收藏');
  check(await page.getByRole('button', { name: '查看Nutella 榛子可可酱', exact: true }).count() === 1, '收藏后的食品可在收藏筛选中找到');
  await click('最近');
  await page.getByRole('button', { name: '按上次份量添加熟糙米饭', exact: true }).click();
  check((await page.locator('#toast').innerText()).includes('上次 150 g'), '最近食品按上次份量添加并清楚提示数量');
  await click('撤销');
  await page.getByRole('button', { name: '04 创建与修正 →', exact: true }).click();
  await page.getByRole('combobox', { name: '营养基准单位', exact: true }).selectOption('serving');
  check(await page.getByRole('spinbutton', { name: '营养基准数量', exact: true }).inputValue() === '1', '每份基准默认一份，仍允许手动修改数量');
  await page.getByRole('textbox', { name: '食品名称', exact: true }).fill('单次食品示例');
  await page.getByRole('spinbutton', { name: '热量', exact: true }).fill('80');
  await page.locator('#save-template').uncheck();
  await click('保存并继续记录');
  await page.getByRole('spinbutton', { name: '摄入量', exact: true }).fill('2');
  check(await text('#intake-energy') === '160', '每份食品在界面按份计算，无重量时不猜克数');
  await page.locator('#save-intake').click();
  await page.getByRole('button', { name: '02 食品搜索 →', exact: true }).click();
  await page.getByRole('searchbox').fill('单次食品示例');
  await click('我的');
  check(await page.getByRole('button', { name: '查看单次食品示例', exact: true }).count() === 0, '取消保存模板时不写入我的食品列表');
  await click('最近');
  check(await page.getByRole('button', { name: '查看单次食品示例', exact: true }).count() === 1, '单次食品仍可从已有日记的最近记录找回');
  await page.getByRole('button', { name: '04 创建与修正 →', exact: true }).click();
  await page.locator('#food-photo').setInputFiles('assets/demo/meals/1548807371-30dc1bbe6cb5.jpg');
  await page.waitForFunction(() => document.querySelector('.edit-photo img')?.getAttribute('src').startsWith('data:image/'));
  check(await page.locator('.edit-photo img').count() === 1, '本地食品照片可预览且无需上传到服务端');
  await page.getByRole('button', { name: '03 食品详情 →', exact: true }).click();
  await page.locator('#phone').screenshot({ path: 'output/playwright/m1/detail.png' });
  await page.getByRole('button', { name: '04 创建与修正 →', exact: true }).click();
  await page.getByRole('textbox', { name: '食品名称', exact: true }).fill('家常鸡蛋羹');
  await page.getByRole('spinbutton', { name: '热量', exact: true }).fill('110');
  await page.getByRole('spinbutton', { name: '蛋白质', exact: true }).fill('9');
  await page.getByRole('spinbutton', { name: '脂肪', exact: true }).fill('7');
  await page.getByRole('spinbutton', { name: '碳水化合物', exact: true }).fill('2');
  await page.locator('#phone').screenshot({ path: 'output/playwright/m1/edit.png' });
  await click('暖白 · 柔和');
  await page.getByRole('button', { name: '01 饮食日记 →', exact: true }).click();
  await click('深色模式');
  await page.locator('#phone').screenshot({ path: 'output/playwright/m1/warm-dark.png' });

  const layouts = [];
  for (const width of [320, 360, 412]) {
    await page.setViewportSize({ width, height: 844 });
    await page.goto(base + 'index.html?standalone=1&screen=home');
    for (const screen of ['home', 'search', 'detail', 'edit']) {
      await page.goto(base + `index.html?standalone=1&screen=${screen}`);
      await page.locator('#text-toggle').evaluate(el => el.click());
      const result = await page.evaluate(() => {
        const app = document.querySelector('#app');
        const body = document.querySelector('.screen-body');
        const bounds = app.getBoundingClientRect();
        const bad = [...app.querySelectorAll('input,select,button')].filter(el => {
          const r = el.getBoundingClientRect();
          return r.width > 0 && (r.left < bounds.left - 1 || r.right > bounds.right + 1);
        }).map(el => el.getAttribute('aria-label') || el.textContent.trim());
        return { documentOverflow: document.documentElement.scrollWidth > innerWidth + 1, bodyOverflow: body.scrollWidth > body.clientWidth + 1, bad };
      });
      if (result.documentOverflow || result.bodyOverflow || result.bad.length) throw new Error(`布局溢出 ${width}px ${screen}: ${JSON.stringify(result)}`);
      layouts.push({ width, screen, largeText: true, horizontalOverflow: false });
    }
  }
  passed.push('320/360/412宽度 × 四页 × 1.2倍字号无横向溢出');
  check(errors.length === 0, '浏览器无未处理脚本错误');
  check(external.length === 0, '原型未发出外部网络请求');
  await page.setViewportSize({ width: 1100, height: 980 });
  await page.goto(base + 'index.html');
  await click('重置示例数据');
  return { status: 'passed', checks: passed, layouts, errors, externalRequests: external };
}
